package plugin

import (
	"encoding/json"
	"errors"
	"path"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

// MaxSourceMapBytes bounds the source map beside a built plugin.
const MaxSourceMapBytes = 16 << 20

// sourceMap maps positions in a built plugin, generated by the bundler, back
// to the files it was built from: a version 3 source map.
type sourceMap struct {
	file    string
	sources []string
	// lines holds each generated line's segments, by generated column.
	lines [][]mapSegment
}

type mapSegment struct {
	column       int
	source       int
	line, origin int
}

// parseSourceMap reads the source map of the built file file. It returns nil
// when text is empty or not a source map it can read: positions then stay
// as they are.
func parseSourceMap(text, file string) *sourceMap {
	if text == "" {
		return nil
	}
	var raw struct {
		Version    int      `json:"version"`
		SourceRoot string   `json:"sourceRoot"`
		Sources    []string `json:"sources"`
		Mappings   string   `json:"mappings"`
	}
	if err := json.Unmarshal([]byte(text), &raw); err != nil || raw.Version != 3 {
		return nil
	}
	parsed := &sourceMap{file: file}
	for _, source := range raw.Sources {
		parsed.sources = append(parsed.sources, cleanSourcePath(raw.SourceRoot, source))
	}
	lines, err := decodeMappings(raw.Mappings, len(parsed.sources))
	if err != nil {
		return nil
	}
	parsed.lines = lines
	return parsed
}

// cleanSourcePath shortens a source's path for a stack trace: the bundler
// writes it relative to the map, as ../src/plugin.ts.
func cleanSourcePath(root, source string) string {
	joined := source
	if root != "" {
		joined = path.Join(root, source)
	}
	for strings.HasPrefix(joined, "../") {
		joined = strings.TrimPrefix(joined, "../")
	}
	return strings.TrimPrefix(joined, "./")
}

var errBadMappings = errors.New("malformed source map mappings")

const base64Digits = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

// decodeMappings decodes the mappings of a version 3 source map: lines
// separated by semicolons, segments by commas, each a run of base64 VLQs
// relative to the segment before.
func decodeMappings(mappings string, sources int) ([][]mapSegment, error) {
	var lines [][]mapSegment
	var current []mapSegment
	source, line, origin := 0, 0, 0
	column := 0
	index := 0
	for index <= len(mappings) {
		if index == len(mappings) || mappings[index] == ';' {
			sort.SliceStable(current, func(a, b int) bool { return current[a].column < current[b].column })
			lines = append(lines, current)
			current = nil
			column = 0
			index++
			continue
		}
		if mappings[index] == ',' {
			index++
			continue
		}
		var fields [5]int
		count := 0
		for index < len(mappings) && mappings[index] != ',' && mappings[index] != ';' {
			value, next, err := decodeVLQ(mappings, index)
			if err != nil {
				return nil, err
			}
			if count < len(fields) {
				fields[count] = value
			}
			count++
			index = next
		}
		column += fields[0]
		if count >= 4 {
			source += fields[1]
			line += fields[2]
			origin += fields[3]
			if source < 0 || source >= sources || line < 0 || origin < 0 {
				return nil, errBadMappings
			}
			current = append(current, mapSegment{column: column, source: source, line: line, origin: origin})
		}
	}
	return lines, nil
}

func decodeVLQ(text string, index int) (value, next int, err error) {
	shift := 0
	for {
		if index >= len(text) {
			return 0, 0, errBadMappings
		}
		digit := strings.IndexByte(base64Digits, text[index])
		if digit < 0 || shift > 30 {
			return 0, 0, errBadMappings
		}
		index++
		value |= (digit & 31) << shift
		if digit&32 == 0 {
			break
		}
		shift += 5
	}
	if value&1 == 1 {
		return -(value >> 1), index, nil
	}
	return value >> 1, index, nil
}

// position maps a 1-based line and column of the built file to the source,
// line and column it came from.
func (parsed *sourceMap) position(line, column int) (string, int, int, bool) {
	if line < 1 || line > len(parsed.lines) {
		return "", 0, 0, false
	}
	segments := parsed.lines[line-1]
	at := sort.Search(len(segments), func(index int) bool { return segments[index].column > column-1 }) - 1
	if at < 0 {
		if len(segments) == 0 {
			return "", 0, 0, false
		}
		at = 0
	}
	segment := segments[at]
	return parsed.sources[segment.source], segment.line + 1, segment.origin + 1, true
}

// rewrite replaces the built file's positions in a stack trace or message
// with the source positions they came from.
func (parsed *sourceMap) rewrite(text string) string {
	pattern := positionPattern(parsed.file)
	return pattern.ReplaceAllStringFunc(text, func(match string) string {
		parts := pattern.FindStringSubmatch(match)
		line, _ := strconv.Atoi(parts[1])
		column, _ := strconv.Atoi(parts[2])
		source, mappedLine, mappedColumn, ok := parsed.position(line, column)
		if !ok {
			return match
		}
		return source + ":" + strconv.Itoa(mappedLine) + ":" + strconv.Itoa(mappedColumn)
	})
}

func positionPattern(file string) *regexp.Regexp {
	return regexp.MustCompile(regexp.QuoteMeta(file) + `:(\d+):(\d+)`)
}
